profiles.single-node:
prometheus:
  # Metrics on the pod port; no Prometheus operator assumed.
  enabled: true
  servicemonitor:
    enabled: false
# Idles at 20-40Mi; small requests fit a 2 GB node.
resources:
  requests: {cpu: 10m, memory: 32Mi}
  limits: {memory: 128Mi}
webhook:
  # Same sizing as the controller.
  resources:
    requests: {cpu: 10m, memory: 24Mi}
    limits: {memory: 64Mi}
cainjector:
  # Caches watched Secrets; the limit bounds it.
  resources:
    requests: {cpu: 10m, memory: 32Mi}
    limits: {memory: 128Mi}
startupapicheck:
  # Short-lived post-install Job.
  resources:
    requests: {cpu: 10m, memory: 16Mi}
    limits: {memory: 64Mi}

smoke.manifest:
apiVersion: cert-manager.io/v1
kind: Issuer
metadata: {name: smoke, namespace: catalog-smoke}
spec: {selfSigned: {}}
---
apiVersion: cert-manager.io/v1
kind: Certificate
metadata: {name: smoke, namespace: catalog-smoke}
spec:
  secretName: smoke-tls
  dnsNames: [smoke.example.test]
  issuerRef: {kind: Issuer, name: smoke}

profiles.single-node:
reloader:
  deployment:
    resources:
      # Caches every ConfigMap and Secret; grows with their count.
      requests: {cpu: 10m, memory: 64Mi}
      limits: {memory: 256Mi}

smoke.manifest:
apiVersion: v1
kind: ConfigMap
metadata: {name: smoke, namespace: catalog-smoke}
data: {revision: "2"}

profiles.multi-node:
operator:
  # Leader-elected standby survives node drains.
  replicaCount: 2
resources:
  # Room for a few hundred ScaledObjects.
  operator:
    requests: {cpu: 50m, memory: 128Mi}
    limits: {memory: 512Mi}
  metricServer:
    requests: {cpu: 50m, memory: 96Mi}
    limits: {memory: 512Mi}
  webhooks:
    requests: {cpu: 20m, memory: 48Mi}
    limits: {memory: 256Mi}

profiles.single-node:
resources:
  # Chart defaults (100Mi/1000Mi) far exceed idle use.
  operator:
    requests: {cpu: 20m, memory: 64Mi}
    limits: {memory: 256Mi}
  metricServer:
    requests: {cpu: 20m, memory: 48Mi}
    limits: {memory: 256Mi}
  webhooks:
    requests: {cpu: 10m, memory: 32Mi}
    limits: {memory: 128Mi}

profiles.multi-node:
agent:
  resources:
    # One agent per node; busier logs than single-node.
    requests: {cpu: 50m, memory: 64Mi}
    limits: {memory: 256Mi}
lapi:
  resources:
    # Headroom for more agents and decisions.
    requests: {cpu: 50m, memory: 96Mi}
    limits: {memory: 384Mi}

profiles.single-node:
agent:
  resources:
    # Chart asks 250Mi; an idle agent uses under 100Mi.
    requests: {cpu: 20m, memory: 48Mi}
    limits: {memory: 192Mi}
lapi:
  resources:
    # Chart asks 500Mi; LAPI on SQLite idles far below.
    requests: {cpu: 20m, memory: 64Mi}
    limits: {memory: 256Mi}

resources:
  # The chart's 200Mi request is sized for 100+ nodes.
  requests: {cpu: 20m, memory: 48Mi}
  limits: {memory: 128Mi}

resources:
